$bytes = [Convert]::FromBase64String(($payload -replace '\s',''))
$sha = [Security.Cryptography.SHA256]::Create()
$hash = ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()
if ($hash -ne '8a4fad84de62101e0680b843194197e43b9f80b9aea18bd3c35ef2a876b269df') { throw 'Il pacchetto non e integro. Nessun file del progetto e stato estratto.' }
$zip = Join-Path $dest 'forma-crm-locale.zip'
[IO.File]::WriteAllBytes($zip,$bytes)
Expand-Archive -LiteralPath $zip -DestinationPath $dest
Write-Host ''
Write-Host 'Progetto e ZIP ricreati correttamente.' -ForegroundColor Green
Write-Host ('Cartella: ' + $dest)
Write-Host ('Avvio: ' + (Join-Path $dest 'forma-crm-locale\Avvia Forma.bat'))
Write-Host 'Per avviare il CRM serve Node.js LTS 20 o successivo: https://nodejs.org'
Write-Host 'Il CRM salva i dati nel browser: esporta regolarmente un backup dalle Impostazioni.'
